package main

import (
	"database/sql"
	"fmt"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		panic(err)
	}
}

// searchProducts handles product search with optional category filter
func searchProducts(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query().Get("q")
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")

	if query == "" {
		http.Error(w, "missing search query", http.StatusBadRequest)
		return
	}

	// Sanitize query - remove obvious dangerous characters
	query = strings.ReplaceAll(query, ";", "")
	query = strings.ReplaceAll(query, "--", "")

	baseSQL := fmt.Sprintf("SELECT id, name, price, description FROM products WHERE name ILIKE '%%%s%%'", query)

	if category != "" {
		// Category is validated against known list
		validCategories := map[string]bool{"electronics": true, "books": true, "clothing": true, "home": true}
		if validCategories[strings.ToLower(category)] {
			baseSQL += fmt.Sprintf(" AND category = '%s'", category)
		}
	}

	// Sort parameter - only allow specific columns
	switch sortBy {
	case "price_asc":
		baseSQL += " ORDER BY price ASC"
	case "price_desc":
		baseSQL += " ORDER BY price DESC"
	case "name":
		baseSQL += " ORDER BY name ASC"
	default:
		baseSQL += " ORDER BY relevance DESC"
	}

	baseSQL += " LIMIT 50"

	rows, err := db.Query(baseSQL)
	if err != nil {
		http.Error(w, "search failed", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(",\n"))
		}
		first = false
		json := fmt.Sprintf(`{"id":%d,"name":"%s","price":%.2f,"description":"%s"}`, id, name, price, description)
		w.Write([]byte(json))
	}
	w.Write([]byte("\n]"))
}

// healthCheck for load balancer
func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchProducts)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	fmt.Printf("Listening on :%s\n", port)
	http.ListenAndServe(":"+port, nil)
}
